exec timeout --kill-after=5s 210s docker exec -i -e QA_CAPABILITY='"'"'{{ OwnershipCapability }}'"'"' -e QA_ACTION='"'"'{{ Action }}'"'"' -e QA_TENANT='"'"'{{ TenantCode }}'"'"' -e QA_RELEASE='"'"'{{ ReleaseId }}'"'"' -e QA_DIGEST='"'"'{{ ApiDigest }}'"'"' -e QA_IMAGE="$image" academy-api python - <<'"'"'ACADEMY_QA_PY'"'"'
import hashlib, hmac, io, json, os, re, signal, sys
import boto3, django
from contextlib import redirect_stdout, redirect_stderr
from pathlib import Path
from botocore.config import Config

LEGACY_RESIDUE_RELEASE = "sha-db54b32e6e33538b320aedbc13fd6011090e961a-run-33825614585-1"
LEGACY_RESIDUE_DIGEST = "sha256:7cd21c84866b296129d68f6fb2d7b420ab29a2bc33b42e44845a719cdaaa525b"
LEGACY_ACTIVITY_AUDIT_ACTIONS = (
    "student_activity.login",
    "student_activity.screen_view",
    "student_activity.target_open",
)

def select_residue_mode(command, release, digest):
    methods = tuple(callable(getattr(command, name, None)) for name in (
        "_cleanup_ephemeral_evidence",
        "_owned_database_residue",
        "_non_database_residue",
    ))
    if all(methods):
        return "native"
    if any(methods):
        raise RuntimeError("Partial development QA residue capability")
    if (release, digest) == (LEGACY_RESIDUE_RELEASE, LEGACY_RESIDUE_DIGEST):
        return "legacy"
    raise RuntimeError("Unsupported development QA residue capability")

def legacy_owned_activity_rows(tenant, user_ids):
    from apps.core.models import OpsAuditLog
    from django.utils import timezone
    activity_rows = OpsAuditLog.objects.filter(
        action__in=LEGACY_ACTIVITY_AUDIT_ACTIONS,
        target_tenant=tenant,
        target_user_id__in=user_ids,
        actor_user_id__in=user_ids,
        created_at__lte=timezone.now(),
    )
    ownership_started_at = (
        OpsAuditLog.objects.filter(
            action="development.qa.setup",
            target_tenant=tenant,
            result="success",
            payload__tenant_code=tenant.code,
            payload__tenant_id=tenant.id,
        )
        .order_by("created_at")
        .values_list("created_at", flat=True)
        .first()
    )
    if ownership_started_at is None:
        if activity_rows.exists():
            raise PermissionError("Refusing legacy activity cleanup without an exact QA ownership seal")
        return activity_rows.none()
    return activity_rows.filter(created_at__gte=ownership_started_at)

def legacy_cleanup_ephemeral_evidence(tenant):
    from apps.core.models import OpsAuditLog
    from rest_framework_simplejwt.token_blacklist.models import OutstandingToken
    user_ids = list(tenant.users.values_list("id", flat=True))
    token_rows = OutstandingToken.objects.filter(user_id__in=user_ids)
    token_ids = list(token_rows.values_list("id", flat=True))
    activity_rows = legacy_owned_activity_rows(tenant, user_ids)
    activity_ids = list(activity_rows.values_list("id", flat=True))
    if activity_ids:
        OpsAuditLog.objects.filter(id__in=activity_ids).delete()
    if token_ids:
        OutstandingToken.objects.filter(id__in=token_ids).delete()
    remaining = {
        "activity_audits": OpsAuditLog.objects.filter(id__in=activity_ids).count(),
        "outstanding_tokens": OutstandingToken.objects.filter(id__in=token_ids).count(),
    }
    if any(remaining.values()):
        raise RuntimeError("Legacy development QA database residue remains")
    return {"remaining": remaining}

def legacy_database_residue(tenant):
    from rest_framework_simplejwt.token_blacklist.models import OutstandingToken
    user_ids = list(tenant.users.values_list("id", flat=True))
    return {
        "activity_audits": legacy_owned_activity_rows(tenant, user_ids).count(),
        "outstanding_tokens": OutstandingToken.objects.filter(user_id__in=user_ids).count(),
    }

def legacy_non_database_residue(*, tenant_id, tenant_code):
    from django.conf import settings
    client = boto3.client(
        "s3",
        endpoint_url=settings.R2_ENDPOINT,
        region_name=settings.R2_REGION,
        aws_access_key_id=settings.R2_ACCESS_KEY,
        aws_secret_access_key=settings.R2_SECRET_KEY,
        config=Config(connect_timeout=10, read_timeout=10, retries={"total_max_attempts": 2}),
    )
    r2_objects = 0
    if tenant_id is not None:
        for prefix in (
            f"tenants/{tenant_id}/",
            f"excel/{tenant_id}/",
            f"tenant-logos/{tenant_id}/",
            f"landing-public/reviews/{tenant_id}/",
            f"matchup-showcase-snapshots/tenant_{tenant_id}/",
        ):
            continuation_token = None
            while True:
                request = {"Bucket": settings.R2_STORAGE_BUCKET, "Prefix": prefix, "MaxKeys": 1000}
                if continuation_token:
                    request["ContinuationToken"] = continuation_token
                page = client.list_objects_v2(**request)
                r2_objects += len(page.get("Contents") or [])
                if not page.get("IsTruncated"):
                    break
                continuation_token = page["NextContinuationToken"]
    marker = f"QA_TENANT={tenant_code}".encode()
    processes = 0
    for entry in Path("/proc").iterdir():
        if not entry.name.isdigit() or int(entry.name) == os.getpid():
            continue
        try:
            environment = (entry / "environ").read_bytes().split(b"\0")
        except (FileNotFoundError, PermissionError, ProcessLookupError):
            continue
        if marker in environment:
            processes += 1
    expected_port = f"{18000:04X}"
    listeners = 0
    for filename in ("/proc/net/tcp", "/proc/net/tcp6"):
        for line in Path(filename).read_text().splitlines()[1:]:
            columns = line.split()
            if len(columns) >= 4 and columns[1].rsplit(":", 1)[-1] == expected_port and columns[3] == "0A":
                listeners += 1
    return {"listeners": listeners, "processes": processes, "r2_objects": r2_objects}

def owned_database_residue(command, mode, tenant):
    if mode == "native":
        return command._owned_database_residue(tenant)
    return legacy_database_residue(tenant)

def non_database_residue(command, mode, *, tenant_id, tenant_code):
    if mode == "native":
        return command._non_database_residue(tenant_id=tenant_id, tenant_code=tenant_code)
    return legacy_non_database_residue(tenant_id=tenant_id, tenant_code=tenant_code)

def ownership_payload(tenant, tenant_id, capability):
    if not re.fullmatch(r"[a-f0-9]{64}", capability):
        raise PermissionError("Invalid ownership capability")
    return {"schema": "frontend-development-qa/v1", "tenant_code": tenant,
            "tenant_id": tenant_id, "owner_sha256": hashlib.sha256(
                (tenant + ":" + str(tenant_id) + ":" + capability).encode()).hexdigest()}

def assert_cleanup_owner(tenant, tenant_id, capability, records):
    expected = ownership_payload(tenant, tenant_id, capability)
    if len(records) != 1 or not isinstance(records[0], dict):
        raise PermissionError("Missing or ambiguous QA creation ownership")
    record = records[0]
    if (set(record) != set(expected)
            or any(record[key] != expected[key] for key in ("schema", "tenant_code", "tenant_id"))
            or not isinstance(record["owner_sha256"], str)
            or not hmac.compare_digest(record["owner_sha256"], expected["owner_sha256"])):
        raise PermissionError("QA cleanup ownership mismatch")

def operation_timeout(_signum, _frame):
    raise TimeoutError("Fixed QA operation deadline exceeded")

def run():
    django.setup()
    from django.conf import settings
    from django.core.management import call_command
    from django.db import connection, transaction
    from apps.core.models import OpsAuditLog
    from apps.core.management.commands.setup_ymath_realuse_scenario import Command, assert_isolated_runtime
    action = os.environ["QA_ACTION"]
    capability = os.environ["QA_CAPABILITY"]
    assert re.fullmatch(r"[a-f0-9]{64}", capability)
    tenant = os.environ["QA_TENANT"]
    release = os.environ["QA_RELEASE"]
    digest = os.environ["QA_DIGEST"]
    assert action in {"Inspect", "Setup", "Cleanup"}
    assert re.fullmatch(r"qa-ymath-realuse-fe-[0-9]+-[0-9]+-[a-f0-9]{12}", tenant)
    assert re.fullmatch(r"sha-[a-f0-9]{40}-run-[0-9]+-[0-9]+", release)
    assert re.fullmatch(r"sha256:[a-f0-9]{64}", digest)
    assert os.environ["DJANGO_SETTINGS_MODULE"] == "apps.api.config.settings.development"
    assert os.environ["ACADEMY_RUNTIME_ENV"] == "development"
    assert os.environ["ACADEMY_DEVELOPMENT_RELEASE_ID"] == release
    assert os.environ["QA_IMAGE"] == "809466760795.dkr.ecr.ap-northeast-2.amazonaws.com/academy-api@" + digest
    assert os.environ.get("SOLAPI_MOCK", "").lower() in {"1", "true", "yes"}
    assert os.environ.get("TOSS_AUTO_BILLING_ENABLED", "").lower() not in {"1", "true", "yes"}
    assert not settings.VIDEO_BATCH_JOB_QUEUE and not settings.VIDEO_BATCH_JOB_DEFINITION
    for key in ("AI_SQS_QUEUE_NAME_LITE", "AI_SQS_QUEUE_NAME_BASIC", "AI_SQS_QUEUE_NAME_PREMIUM"):
        assert os.environ[key] == "academy-v1-development-ai-queue"
    assert settings.TOOLS_SQS_QUEUE_NAME == "academy-v1-development-tools-queue"
    assert settings.MESSAGING_SQS_QUEUE_NAME == "academy-v1-development-messaging-queue"
    assert settings.DATABASES["default"]["NAME"] == "academy_api_development"
    assert settings.DATABASES["default"]["USER"] == "academy_api_development_app"
    assert all(getattr(settings, key) == "academy-development-artifacts" for key in
               ("R2_AI_BUCKET", "R2_STORAGE_BUCKET", "R2_ADMIN_BUCKET", "R2_VIDEO_BUCKET", "R2_EXCEL_BUCKET"))
    assert_isolated_runtime()
    command = Command()
    residue_mode = select_residue_mode(command, release, digest)
    remaining = command._remaining_for_code(tenant)
    if action == "Inspect":
        residue = {"activity_audits": 0, "outstanding_tokens": 0, "listeners": 0,
                   "processes": 0, "r2_objects": 0}
        tenant_id = None
        if remaining["tenants"] == 1:
            existing = command._exact_tenant_or_fail_on_case_variant(tenant)
            tenant_id = existing.pk
            residue.update(owned_database_residue(command, residue_mode, existing))
        residue.update(non_database_residue(command, residue_mode, tenant_id=tenant_id, tenant_code=tenant))
        return {"status": "DEVELOPMENT_QA_IDENTITY_PASS", "tenant_code": tenant, "release_id": release,
                "digest": digest, "remaining": remaining, "residue": residue}
    output = io.StringIO()
    subject = None
    subject_id = None
    database_cleanup = None
    with transaction.atomic():
        with connection.cursor() as cursor:
            cursor.execute("SET LOCAL statement_timeout = '"'"'150s'"'"'")
            cursor.execute("SET LOCAL lock_timeout = '"'"'5s'"'"'")
        command._lock_tenant_code(tenant)
        existing = command._exact_tenant_or_fail_on_case_variant(tenant)
        if action == "Setup":
            assert existing is None
            assert command._remaining_for_code(tenant) == {"tenants": 0, "users": 0}
            secret = boto3.client("ssm", region_name="ap-northeast-2",
                                  config=Config(connect_timeout=10, read_timeout=10,
                                                retries={"total_max_attempts": 2})).get_parameter(
                Name="/academy/api/development/ymath-realuse-password", WithDecryption=True)
            os.environ["YMATH_REALUSE_SCENARIO_PASSWORD"] = secret["Parameter"]["Value"]
            try:
                call_command("setup_ymath_realuse_scenario", tenant_code=tenant, student_count=1, session_count=1, stdout=output)
                created = command._exact_tenant_or_fail_on_case_variant(tenant)
                assert created is not None
                subject = created
                subject_id = created.pk
                OpsAuditLog.objects.create(
                    action="development.qa.setup", target_tenant=created,
                    actor_username="frontend-release-runner",
                    payload=ownership_payload(tenant, created.pk, capability), result="success")
            finally:
                os.environ.pop("YMATH_REALUSE_SCENARIO_PASSWORD", None)
        else:
            if existing is None:
                assert command._remaining_for_code(tenant) == {"tenants": 0, "users": 0}
                residue = {"activity_audits": 0, "outstanding_tokens": 0, "listeners": 0,
                           "processes": 0, "r2_objects": 0}
                residue.update(command._non_database_residue(tenant_id=None, tenant_code=tenant))
                assert residue == {"activity_audits": 0, "outstanding_tokens": 0, "listeners": 0,
                                   "processes": 0, "r2_objects": 0}
                return {"status": "YMATH_REALUSE_SCENARIO_ABSENT", "tenant_code": tenant,
                        "remaining": {"tenants": 0, "users": 0}, "residue": residue}
            records = list(OpsAuditLog.objects.filter(
                action="development.qa.setup", target_tenant=existing, result="success"
            ).values_list("payload", flat=True)[:2])
            assert_cleanup_owner(tenant, existing.pk, capability, records)
            subject_id = existing.pk
            if residue_mode == "legacy":
                database_cleanup = legacy_cleanup_ephemeral_evidence(existing)
            call_command("setup_ymath_realuse_scenario", tenant_code=tenant, destroy=True, stdout=output)
    payload = json.loads(output.getvalue().strip().splitlines()[-1])
    assert payload["tenant_code"] == tenant
    if action == "Setup":
        payload["residue"] = owned_database_residue(command, residue_mode, subject)
    elif residue_mode == "native":
        assert payload["residue"] == {"activity_audits": 0, "outstanding_tokens": 0}
    else:
        assert database_cleanup is not None
        payload["residue"] = database_cleanup["remaining"]
    payload["residue"].update(non_database_residue(
        command, residue_mode, tenant_id=subject_id, tenant_code=tenant))
    assert payload["residue"] == {"activity_audits": 0, "outstanding_tokens": 0, "listeners": 0,
                                  "processes": 0, "r2_objects": 0}
    if action == "Cleanup":
        assert payload["remaining"] == {"tenants": 0, "users": 0}
    return payload

try:
    signal.signal(signal.SIGALRM, operation_timeout)
    signal.alarm(180)
    with redirect_stdout(io.StringIO()), redirect_stderr(io.StringIO()):
        result = run()
    signal.alarm(0)
    print(json.dumps(result, sort_keys=True))
except Exception as error:
    print(json.dumps({"status": "DEVELOPMENT_QA_FAILED", "error_type": type(error).__name__}))
    sys.exit(1)
ACADEMY_QA_PY'
